quentBehaviornotes": null, "EatingDisturbancerating": "0", "RecklessBehaviorsrating": "0", "communityvoilancerating": "0", "DelinquentBehaviorrating": "0", "OppositionalBehaviornotes": null, "OppositionalBehaviorrating": "0", "AttachmentDifficultiesnotes": null, "DepressionMoodDisordernotes": null, "IntentionalMisbehaviornotes": null, "SelfInjuriousBehaviorsnotes": null, "AttachmentDifficultiesrating": "0", "DepressionMoodDisorderrating": "0", "IntentionalMisbehaviorrating": "0", "SelfInjuriousBehaviorsrating": "0", "SexuallyReactiveBehaviornotes": null, "AttnDeficitImpulseControlnotes": null, "ConductAntisocialBehaviornotes": null, "AttnDeficitImpulseControlrating": "0", "ConductAntisocialBehaviorrating": "0", "SexuallyReactiveBehaviorsrating": "0"}], "careGiver": [{"org": null, "orgnotes": "She has a lot of children and a lot of appointments but seems to keep things pretty well organized. She probably just waits to long to ensure she has transportation, etc. ", "knowledge": true, "listening": true, "orgrating": "1", "boundaries": null, "discipline": true, "formStatus": true, "serviceopt": true, "involvement": null, "supervision": null, "youthliving": true, "Anxietynotes": null, "neglectnotes": null, "runawaynotes": null, "Anxietyrating": "0", "bullyingnotes": null, "caregiverlist": "6079f244-72ac-4a4e-8872-f8aedd077e96", "communication": true, "disasternotes": null, "emotionalresp": null, "famchildneeds": true, "naturesupport": null, "neglectrating": "0", "phyabusenotes": null, "runawayrating": "0", "sexabusenotes": null, "Exploitednotes": null, "Psychosisnotes": null, "bullyingrating": "0", "disasterrating": "0", "knowledgenotes": null, "listeningnotes": "This has been a strength after this worker''s initial visit to the home when she made worker leave and later apologized for her actions. She''s listened to things that were hard to hear and didn''t get upset or angry but rather appreciated the understanding and openness provided to her.", "medtraumanotes": "The birth of her oldest and youngest child would have been traumatic due to their special needs and the rupturing of her uterus.", "phyabuserating": "0", "phyhealthnotes": "She has Narcolepsy, nerve issues and blood clots. Her last pregnancy was complicated and she suffered a ruptured uterus; she''s not been back to the doctors to see how she''s healed", "servicearrange": true, "sexabuserating": "0", "youtheducation": null, "Exploitedrating": "0", "Psychosisrating": "0", "boundariesnotes": null, "disciplinenotes": "There has never been any concerns regarding her physically hurting the children.", "disruptionnotes": "She''s never lost care of her children but she''s been separated from them due to hospitalizations and is currently struggling feeling guilty and sad not being there more for Artemis and also resenting the situation where she has little support which requires her to be with the other kids and away from him. Ms. Hewitt is considering adopting Artemis out so someone can provide him everything he needs because she recognizes she''s already stretched too thin and she''s struggling. ", "knowledgerating": "0", "listeningrating": "1", "medtraumarating": "1", "phyhealthrating": "2", "serviceoptnotes": "She''s a parent to 5 children, all of which have some special need. She''s familiar with community resources and at times uses them successfully.", "SuicideRisknotes": null, "boundariesrating": "0", "disciplinerating": "0", "disruptionrating": "1", "firesettingnotes": null, "involvementnotes": "If she chooses to keep Artemis she''s going to have to make herself available to be trained on all the necessary medical conditions.", "responsibilities": true, "serviceoptrating": "0", "supervisionnotes": "Past issues of Jabez and Sofia being outside unattended. Issues with Ms. Hewitt not being there to get Chloe off the bus. She was making a bottle when Gabriel reportedly \"helped\" as the baby cried and MAY have resulted in the fracture. She does have rules for the children not to pick up the baby. ", "waraffectednotes": null, "youthlivingnotes": "Other than she is considering adoption for Artemis", "AngerControlnotes": null, "SuicideRiskrating": "0", "contactcaregivers": [], "firesettingrating": "0", "involvementrating": "3", "mentalhealthnotes": "Ms. Hewitt is diagnosed with PTSD, Bipolar type I, Borderline Personality, anxiety, ADHD. She''s taking GAbopentin and sees DR. Syed at the Mental Health Center and Lawerence. She had PCM in the past and needs to re-engage with them or another case management service for ongoing assistance.", "substanceusenotes": "It''s been reported she''s smelled like marijuana and has used in the past. She was prescribed medication during the pregnancy. It''s hard to tell how much is her mental health or possibly substance use/abuse even of her prescribed medication. ", "supervisionrating": "2", "waraffectedrating": "0", "youthlivingrating": "0", "AngerControlrating": "0", "communicationnotes": "At times Ms. Hewitt lashes out but will later apologize for her outburst. She''s well spoken and able to provide a lot of insight into things she needs help with, struggles with, etc. ", "criminalbehavnotes": null, "developmentalnotes": "She has a 9th grade education. Previously she''s expressed an interest in getting her GED. ", "emotionalrespnotes": "Ms. Hewitt loves her children and wants what''s best for them; however, her own depression and anxiety make it difficult to sometimes be there for the children how they need her to. She admits when she''s depressed she shuts down and doesn''t want to be around people.", "famchildneedsnotes": null, "mentalhealthrating": "3", "naturesupportnotes": "Ms. Hewitt has her mother as her sole support. Jabez and Sofia''s paternal grandparents will help but the relationship between her and their father and them at times is strained. ", "posttraumaticnotes": "She is diagnosed with PTSD", "substanceuserating": "1", "DangertoOthersnotes": null, "SubstanceAbusenotes": null, "communicationrating": "1", "criminalbehavrating": "0", "developmentalrating": "1", "emotionalabusenotes": null, "emotionalresprating": "2", "famchildneedsrating": "0", "familyvoilancenotes": null, "naturesupportrating": "3", "posttraumaticrating": "3", "schoolvoilancenotes": null, "servicearrangenotes": "She''s open and acknowledges even if Artemis isn''t living in the home she needs ongoing supports to assist with referrals, transportation, connection to community services/activities for the children", "terroraffectednotes": null, "youtheducationnotes": null, "DangertoOthersrating": "0", "SubstanceAbuserating": "0", "addl_crgvr_info_pmsl": "", "emotionalabuserating": "0", "familyvoilancerating": "0", "schoolvoilancerating": "0", "servicearrangerating": "0", "terroraffectedrating": "0", "youtheducationrating": "0", "SexualAggressionnotes": null, "addl_crgvr_advcy_info": "As with anyone, Ms. Hewitt responds best to transparency and empathy when dealing with all situations. She knows her children''s needs and wants to meet them all and would really benefit from some respite for herself at times as a way to \"refresh/rejuvenate.\" She wants to provide her children with a \"normal\" childhood but acknowledges her own limitations with mental health as well as the physical limitations of pushing multiple strollers/wheelchairs while keeping track of two other children.", "criminalactivitynotes": null, "responsibilitiesnotes": "She knows her rights. ", "EatingDisturbancenotes": null, "RecklessBehaviorsnotes": null, "SexualAggressionrating": "0", "communityvoilancenotes": null, "criminalactivityrating": "0", "responsibilitiesrating": "0", "DelinquentBehaviornotes": null, "EatingDisturbancerating": "0", "RecklessBehaviorsrating": "0", "communityvoilancerating": "0", "DelinquentBehaviorrating": "0", "OppositionalBehaviornotes": null, "OppositionalBehaviorrating": "0", "AttachmentDifficultiesnotes": null, "DepressionMoodDisordernotes": null, "IntentionalMisbehaviornotes": null, "SelfInjuriousBehaviorsnotes": null, "AttachmentDifficultiesrating": "0", "DepressionMoodDisorderrating": "0", "IntentionalMisbehaviorrating": "0", "SelfInjuriousBehaviorsrating": "0", "SexuallyReactiveBehaviornotes": null, "AttnDeficitImpulseControlnotes": null, "ConductAntisocialBehaviornotes": null, "AttnDeficitImpulseControlrating": "0", "ConductAntisocialBehaviorrating": "0", "SexuallyReactiveBehaviorsrating": "0", "contactprofesssionalsupcaregivers": []}], "familyYouth": {"childAge": null, "childDob": null, "childName": null, "childArray": [{"childAge": "12 Yrs", "childDob": "2007-12-29T05:00:00.000Z", "childName": "b0a9d2bf-eb74-49e6-ad74-9132fecae9c9", "childSchool": "", "childNameText": "CHLOE ASHLYNN HEWITT", "childRelationship": ""}, {"childAge": "6 Yrs", "childDob": "2014-03-17T04:00:00.000Z", "childName": "309f4d4f-3af3-4aaa-82fd-55d4e5f81458", "childSchool": "Kindergarten", "childNameText": "SOFIA ELAINE LEWIS", "childRelationship": ""}, {"childAge": "9 Yrs", "childDob": "2010-08-16T04:00:00.000Z", "childName": "c94a5012-75e1-442a-b491-d43bb6ad0874", "childSchool": "", "childNameText": "GABRIEL  HEWITT", "childRelationship": ""}, {"childAge": "4 Yrs", "childDob": "2015-06-15T04:00:00.000Z", "childName": "8bb00775-0ac3-45f3-b9f5-0242e9bda8a2", "childSchool": "", "childNameText": "JABEZ C LEWIS", "childRelationship": ""}, {"childAge": "4 Month(s)", "childDob": "2019-11-11T05:00:00.000Z", "childName": "d40bda0b-5a58-4885-9cb4-e21fc6b6ea13", "childSchool": "", "childNameText": " Artemis  Fowler ", "childRelationship": "Biological Child"}], "childSchool": null, "houseHoldId": "2020057016138", "servicename": null, "caregiverage": null, "caregiverdob": null, "serviceArray": [{"servicename": "Mental Health Center-Christina and Gabriel", "currentorpast": "Current", "servicehelpful": null}, {"servicename": "Simply Kidz-Gabriel", "currentorpast": "Current", "servicehelpful": null}, {"servicename": "South Side Pediatrics-Chloe, Sofia, Jabez & Artemis", "currentorpast": "Current", "servicehelpful": null}, {"servicename": "Children''s National-Artemis & Chloe", "currentorpast": "Current", "servicehelpful": null}, {"servicename": "PCM-Gabriel; mother needs re-engaged", "currentorpast": null, "servicehelpful": null}, {"servicename": "Pine Dentistry", "currentorpast": null, "servicehelpful": null}, {"servicename": "DDA-Gabriel & Chloe", "currentorpast": null, "servicehelpful": null}], "caregivername": null, "houseHoldHead": "6079f244-72ac-4a4e-8872-f8aedd077e96", "houseHoldName": "CHRISTINA HEWITT", "caregiverArray": [{"caregiverage": "32 Yrs", "caregiverdob": "1988-01-03T05:00:00.000Z", "caregivername": "6079f244-72ac-4a4e-8872-f8aedd077e96", "caregivernametext": "CHRISTINA  HEWITT", "caregiverrelationship": "Self"}], "referralsource": "South Side Pediatrics reported that Artemis had missed appointments and the family didn''t have the necessary supplies for his G-tube; mother had been feeding by mouth. The discharge summary from Hospital for Sick Children (HSC) reports he was taking all feeds by mouth and medication via G-tube. They recommended regular checks to ensure he was doing well feeding by mouth. South Side only saw him twice. Transportation is an issue for the family and lack of supports to care for the other children, especially Chloe who is completely dependent on others to meet her needs.  Worker feels as though Ms. Hewitt needs ongoing supportive services but also believes the medical providers haven''t always been forthcoming with information, done the appropriate monitoring of the child, and despite him being hospitalized he''s continued to lose weight, been given the wrong caloric formula, etc. ", "timeCompletion": "Initial", "caseheaddatetime": "2020-03-20T12:43:18.493Z", "childdescription": null, "childRelationship": null, "caregiverdescription": null, "caregiverrelationship": null}, "supervisorname": "Megan Jordan", "assessmentStaus": "Accepted", "assessmentactor": [{"intakeservicerequestactorid": "b0a9d2bf-eb74-49e6-ad74-9132fecae9c9"}, {"intakeservicerequestactorid": "8bb00775-0ac3-45f3-b9f5-0242e9bda8a2"}, {"intakeservicerequestactorid": "309f4d4f-3af3-4aaa-82fd-55d4e5f81458"}, {"intakeservicerequestactorid": "c94a5012-75e1-442a-b491-d43bb6ad0874"}, {"intakeservicerequestactorid": "d40bda0b-5a58-4885-9cb4-e21fc6b6ea13"}, {"intakeservicerequestactorid": "6079f244-72ac-4a4e-8872-f8aedd077e96"}], "familyCultureYouth": {"ritual_scale": "0", "sexual_scale": "0", "cultural_scale": "0", "language_scale": "0", "ritual_comments": "", "ritual_strength": "", "sexual_comments": "", "cultural_comments": "Jabez and Sofia''s father is part Indian but not registered. ", "cultural_strength": "", "language_comments": "", "language_strength": "", "sexual_identity_strength": "", "additional_acculturation_info": ""}, "routingsupervisors": [{"email": "amanda.bishop@maryland.gov", "userid": "cc32a738-0985-4ac9-8497-cd6b48ba2938", "cjamspid": "100004327", "rolecode": "SP", "roledesc": "CW Supervisor", "teamname": "In Home Services Program Manager", "username": "Amanda Bishop", "userrole": "CW", "agencykey": "CW", "available": "Yes", "workloads": 0, "loadnumber": "6004145", "totalcases": "0", "juridiction": null, "issupervisor": true, "resourcename": null, "homelocationcode": null, "worklocationcode": null}, {"email": "barbara.shevokas@maryland.gov", "userid": "82b1c827-bc1b-456e-a933-7a21a10aeb1e", "cjamspid": "100003889", "rolecode": "SP", "roledesc": "CPS Program Manager", "teamname": "CPS Program Manager", "username": "Barbara Shevokas", "userrole": "CW", "agencykey": "CW", "available": "Yes", "workloads": 0, "loadnumber": "617", "totalcases": "0", "juridiction": null, "issupervisor": true, "resourcename": null, "homelocationcode": null, "worklocationcode": null}, {"email": "christina.mccauley@maryland.gov", "userid": "d5f3081f-42f5-4e19-bc15-1c721fe1789a", "cjamspid": "100004210", "rolecode": "SP", "roledesc": "In-Home Services Worker", "teamname": "CPS Unit 2", "username": "Christina McCauley", "userrole": "CW", "agencykey": "CW", "available": "Yes", "workloads": 0, "loadnumber": "6014770", "totalcases": "0", "juridiction": null, "issupervisor": true, "resourcename": null, "homelocationcode": null, "worklocationcode": null}, {"email": "jennifera.lewis@maryland.gov", "userid": "3385cc0b-0165-44bf-9bce-08e9b3fcb8bf", "cjamspid": "100004333", "rolecode": "SP", "roledesc": "CW Supervisor", "teamname": "Safe Place", "username": "Jennifer Lewis", "userrole": "CW", "agencykey": "CW", "available": "Yes", "workloads": 0, "loadnumber": "6022539", "totalcases": "0", "juridiction": null, "issupervisor": true, "resourcename": null, "homelocationcode": null, "worklocationcode": null}, {"email": "julia.jensen@maryland.gov", "userid": "80025a81-dad5-4345-80d1-f97bddb1dbbc", "cjamspid": "100003870", "rolecode": "SP", "roledesc": "CPS Program Manager", "teamname": "Out of Home Program Manager", "username": "Julia Jensen", "userrole": "CW", "agencykey": "CW", "available": "Yes", "workloads": 0, "loadnumber": "6010237", "totalcases": "0", "juridiction": null, "issupervisor": true, "resourcename": null, "homelocationcode": null, "worklocationcode": null}, {"email": "kathleen.chaney@maryland.gov", "userid": "dd3ac302-59b9-4e32-ac55-94a0d551ee4f", "cjamspid": "100004328", "rolecode": "SP", "roledesc": "CW Supervisor", "teamname": "FC/Adoption Unit 3", "username": "Kathleen Chaney", "userrole": "CW", "agencykey": "CW", "available": "Yes", "workloads": 0, "loadnumber": "6004156", "totalcases": "0", "juridiction": null, "issupervisor": true, "resourcename": null, "homelocationcode": null, "worklocationcode": null}, {"email": "kevin.buckley@maryland.gov", "userid": "293dc438-7f04-41f7-8845-e87304274c6c", "cjamspid": "100004207", "rolecode": "SP", "roledesc": "In-Home Services Supervisor", "teamname": "LDSS Management", "username": "Kevin Buckley", "userrole": "CW", "agencykey": "CW", "available": "Yes", "workloads": 0, "loadnumber": "6004157", "totalcases": "0", "juridiction": 